      "citations": [
        {
          "event_id": "lite_evt_00102",
          "explanation": "医生把路远障碍转换为就近医院次晨评估方案，但这主要属于最低安全责任链要求。",
          "quote": "明天一早去就近的医院心内科门诊"
        }
